import React, { useContext, useReducer, useState } from 'react';
import { UserContext } from '../context/UserContext';
import axios from 'axios';

const estadoInicial = {
    usuario: '',
    contra: '',
    nombre: '',
    apellidos: '',
    fecha_nacimiento: '',
};

const reductorFormulario = (estado, accion) => {
    return { ...estado, [accion.campo]: accion.valor };
};

const FormularioUsuario = () => {
    const { agregarUsuario, patronesValidacion } = useContext(UserContext);
    const [estadoFormulario, despachar] = useReducer(reductorFormulario, estadoInicial);
    const [errores, setErrores] = useState([]);

    const manejarCambio = (e) => {
        despachar({ campo: e.target.name, valor: e.target.value });
    };

    const validarUsuario = (estadoFormulario) => {
        let erroresValidacion = [];
    
        // Validación para el nombre de usuario
        if (!patronesValidacion.usuario.test(estadoFormulario.usuario)) {
            erroresValidacion.push("El nombre de usuario debe tener al menos 6 caracteres, comenzar por una letra y no contener caracteres especiales.");
        }
    
        // Validación para la contraseña
        if (!patronesValidacion.contraseña.test(estadoFormulario.contraseña)) {
            erroresValidacion.push("La contraseña debe tener al menos 8 caracteres, contener una mayúscula y un número.");
        }
    
        // Validación para la fecha de nacimiento
        const fecha_nacimiento = new Date(estadoFormulario.fecha_nacimiento);
        const hoy = new Date();
        const edad = hoy.getFullYear() - fecha_nacimiento.getFullYear();
        const diferenciaMes = hoy.getMonth() - fecha_nacimiento.getMonth();
    
        if (edad < 18 || (edad === 18 && diferenciaMes < 0)) {
            erroresValidacion.push("Debes ser mayor de edad (18 años o más).");
        }
    
        return erroresValidacion;
    };
    

    const manejarEnvio = async (e) => {
        e.preventDefault();
        setErrores([]); // Limpiar los errores previos

        // Validar el estado del formulario
        const erroresValidacion = validarUsuario(estadoFormulario);
        if (erroresValidacion.length > 0) {
            setErrores(erroresValidacion);
            return;
        }

        try {
            const respuesta = await axios.post('http://localhost/SERVIDOR/practica/api.php', estadoFormulario);
            agregarUsuario(respuesta.data);
            despachar({ campo: 'usuario', valor: estadoInicial.usuario });
            despachar({ campo: 'contra', valor: estadoInicial.contra});
            despachar({ campo: 'nombre', valor: estadoInicial.nombre });
            despachar({ campo: 'apellidos', valor: estadoInicial.apellidos });
            despachar({ campo: 'fecha_nacimiento', valor: estadoInicial.fecha_nacimiento });
        } catch (error) {
            console.error("Error al agregar el usuario:", error);
            setErrores(["Ocurrió un error al enviar los datos. Intenta nuevamente."]);
        }
    };

    return (
        <form onSubmit={manejarEnvio}>
            {errores.length > 0 && (
                <ul style={{ color: 'red' }}>
                    {errores.map((err, index) => (
                        <li key={index}>{err}</li>
                    ))}
                </ul>
            )}
            <input type="text" name="usuario" placeholder="Nombre de usuario" value={estadoFormulario.usuario} onChange={manejarCambio} required />
            <input type="password" name="contra" placeholder="Contraseña" value={estadoFormulario.contra} onChange={manejarCambio} required />
            <input type="text" name="nombre" placeholder="Nombre" value={estadoFormulario.nombre} onChange={manejarCambio} required />
            <input type="text" name="apellidos" placeholder="Apellidos" value={estadoFormulario.apellidos} onChange={manejarCambio} required />
            <input type="date" name="fecha_nacimiento" value={estadoFormulario.fecha_nacimiento} onChange={manejarCambio} required />
            <button type="submit">Agregar Usuario</button>
        </form>
    );
};

export default FormularioUsuario;
